CREATE TABLE clients (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom varchar(255) NOT NULL, prenom varchar(255) NOT NULL, email varchar(255) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, role varchar(255) NOT NULL);
CREATE TABLE compte_bancaire (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, date_creation date NOT NULL, solde numeric(19,2) NOT NULL, etat varchar(255) NOT NULL, client_id bigint NOT NULL REFERENCES clients(id), version bigint NOT NULL);
CREATE TABLE compte_courant (id bigint PRIMARY KEY REFERENCES compte_bancaire(id), decouvert numeric(38,2));
CREATE TABLE compte_epargne (id bigint PRIMARY KEY REFERENCES compte_bancaire(id), taux_interet numeric(38,2));
CREATE TABLE operation (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, compte_id bigint NOT NULL REFERENCES compte_bancaire(id), date_operation timestamp(6) with time zone NOT NULL, montant numeric(19,2) NOT NULL, type enum('CREDIT','DEBIT') NOT NULL, reference varchar(255) NOT NULL);
